@classmethod
def _atvp_plugin_id_from_source(cls, source, origin):
    try:
        parsed = urlparse(str(source or "").strip())
        base = urlparse(str(origin or "").strip())
    except Exception:
        return 0
    if (
            parsed.scheme not in ("http", "https")
            or parsed.scheme.lower() != base.scheme.lower()
            or parsed.netloc.lower() != base.netloc.lower()):
        return 0
    match = re.search(
        r"/plugins/[^/]+/(\d+)\.(?:py|txt)$", unquote(parsed.path), re.I,
    )
    return cls._positive_int(match.group(1), 0) if match else 0

@classmethod
def _atvp_plugin_sites_from_subscription(cls, config, origin):
    if not isinstance(config, dict):
        return []
    policy = cls.ATVP_PLUGIN_CANDIDATE_POLICY
    allowlist = policy.get("allowlist") or {}
    self_ids = policy.get("self_ids") or frozenset()
    excluded = tuple(str(value).casefold() for value in policy.get("excluded_name_markers") or ())
    selected = []
    seen = set()
    for position, site in enumerate(config.get("sites") or []):
        if not isinstance(site, dict) or site.get("searchable") in (0, False, "0"):
            continue
        name = str(site.get("name") or site.get("key") or "").strip()
        normalized_name = name.casefold()
        if not normalized_name or any(marker in normalized_name for marker in excluded):
            continue
        payload = cls._atvp_plugin_decode_ext(site.get("ext"))
        if not isinstance(payload, dict):
            continue
        plugin_id = cls._atvp_plugin_id_from_source(payload.get("source"), origin)
        expected_name = str(allowlist.get(plugin_id) or "").strip()
        if (
                not plugin_id or plugin_id in self_ids or plugin_id in seen
                or not expected_name or normalized_name != expected_name.casefold()):
            continue
        seen.add(plugin_id)
        selected.append({
            "position": position,
            "plugin_id": plugin_id,
            "name": name,
            "ext": str(site.get("ext") or ""),
        })
    selected.sort(key=lambda row: (
        list(allowlist).index(row["plugin_id"])
        if row["plugin_id"] in allowlist else len(allowlist),
        row["position"],
    ))
    return selected[:len(allowlist)]

def _atvp_plugin_sites_snapshot(self):
    lock = getattr(self, "_atvp_plugin_lock", None)
    if lock is None:
        return []
    with lock:
        sites = [dict(row) for row in self._atvp_plugin_sites]
    if sites:
        return sites
    try:
        raw_config = self._native_subscription_config_java()
        if raw_config:
            self._apply_native_subscription_config(raw_config)
    except Exception:
        return []
    with lock:
        return [dict(row) for row in self._atvp_plugin_sites]

def _atvp_plugin_fetch_atvp_source(self, deadline=None):
    backend = str(self.atvp_api or "").rstrip("/")
    with self._atvp_plugin_lock:
        if (
                self._atvp_plugin_atvp_source
                and self._atvp_plugin_atvp_source_backend == backend):
            return self._atvp_plugin_atvp_source
    remaining = (
        deadline - time.monotonic()
        if deadline is not None and math.isfinite(deadline) else 10
    )
    if remaining <= 0:
        raise RuntimeError("插件候选加载已超时")
    with self._atvp_plugin_source_lock:
        with self._atvp_plugin_lock:
            if (
                    self._atvp_plugin_atvp_source
                    and self._atvp_plugin_atvp_source_backend == backend):
                return self._atvp_plugin_atvp_source
        response = self._atvp_session.get(
            backend + "/Atvp.py",
            headers={"Accept": "text/plain", "X-CLIENT": "com.fongmi.android.tv"},
            timeout=max(2, min(10, remaining)),
            verify=self.verify_tls,
            stream=True,
        )
        try:
            if response.status_code < 200 or response.status_code >= 300:
                raise RuntimeError("Atvp 适配层 HTTP %s" % response.status_code)
            maximum = self._positive_int(
                self.ATVP_PLUGIN_CANDIDATE_POLICY.get("source_max_bytes"), 512 * 1024,
            )
            content_length = self._positive_int(
                response.headers.get("Content-Length") or response.headers.get("content-length"), 0,
            )
            if content_length > maximum:
                raise RuntimeError("Atvp 适配层源码过大")
            chunks = []
            received = 0
            for chunk in response.iter_content(chunk_size=65536):
                if not chunk:
                    continue
                received += len(chunk)
                if received > maximum:
                    raise RuntimeError("Atvp 适配层源码过大")
                chunks.append(chunk)
            source = b"".join(chunks).decode("utf-8-sig")
        finally:
            response.close()
        if "class Spider" not in source or "def searchContent" not in source:
            raise RuntimeError("Atvp 适配层源码无效")
        with self._atvp_plugin_lock:
            if backend == str(self.atvp_api or "").rstrip("/"):
                self._atvp_plugin_atvp_source = source
                self._atvp_plugin_atvp_source_backend = backend
        return source

def _atvp_plugin_wrapper(self, site, deadline=None):
    plugin_id = self._positive_int((site or {}).get("plugin_id"), 0)
    with self._atvp_plugin_lock:
        cached = self._atvp_plugin_wrappers.get(plugin_id)
    if cached is not None:
        return cached
    source = self._atvp_plugin_fetch_atvp_source(deadline=deadline)
    module = __import__("types").ModuleType("v87_atvp_wrapper_%s" % plugin_id)
    module.__file__ = "<v87-atvp-wrapper-%s>" % plugin_id
    exec(compile(source, module.__file__, "exec"), module.__dict__)
    wrapper_class = getattr(module, "Spider", None)
    if wrapper_class is None:
        raise RuntimeError("Atvp 适配层没有 Spider")
    wrapper_class._instance = None
    wrapper = wrapper_class()
    wrapper.init(str((site or {}).get("ext") or ""))
    with self._atvp_plugin_lock:
        existing = self._atvp_plugin_wrappers.get(plugin_id)
        if existing is None:
            self._atvp_plugin_wrappers[plugin_id] = wrapper
            self._atvp_plugin_call_locks.setdefault(plugin_id, threading.Lock())
            return wrapper
        return existing

def _submit_atvp_plugin_task(self, worker):
    if not self._atvp_plugin_slots.acquire(False):
        return None
    released = [False]
    release_lock = threading.Lock()

    def release_once(_future=None):
        with release_lock:
            if released[0]:
                return
            released[0] = True
        self._atvp_plugin_slots.release()

    try:
        future = self._atvp_plugin_executor.submit(worker)
        future.add_done_callback(release_once)
        return future
    except Exception:
        release_once()
        return None

def _run_atvp_plugin_task(self, worker, deadline=None):
    future = self._submit_atvp_plugin_task(worker)
    if future is None:
        raise RuntimeError("插件候选执行槽位已满")
    remaining = (
        deadline - time.monotonic()
        if deadline is not None and math.isfinite(deadline)
        else self.ATVP_PLUGIN_CANDIDATE_POLICY.get("timeout", 18)
    )
    try:
        return future.result(timeout=max(0.1, remaining))
    except FuturesTimeoutError:
        future.cancel()
        raise RuntimeError("插件候选调用超时")

@classmethod
def _atvp_plugin_raw_id_safe(cls, value):
    raw = str(value or "").strip()
    if not raw or len(raw) > cls.RESOURCE_ID_MAX_LENGTH:
        return False
    decoded = cls._unquote_limited(raw)
    return not (
        cls._contains_url_reference(decoded)
        or re.match(r"^(?:https?://|magnet:|ed2k:|thunder:)", decoded, re.I)
    )

@classmethod
def _atvp_plugin_encode_resource_id(cls, plugin_id, raw_id):
    plugin_id = cls._positive_int(plugin_id, 0)
    raw_id = str(raw_id or "").strip()
    if (
            plugin_id not in (cls.ATVP_PLUGIN_CANDIDATE_POLICY.get("allowlist") or {})
            or not cls._atvp_plugin_raw_id_safe(raw_id)):
        return ""
    payload = json.dumps(
        {"plugin": plugin_id, "id": raw_id}, ensure_ascii=False, separators=(",", ":"),
    ).encode("utf-8")
    encoded = base64.urlsafe_b64encode(payload).decode("ascii").rstrip("=")
    value = str(cls.ATVP_PLUGIN_CANDIDATE_POLICY.get("resource_prefix") or "") + encoded
    return value if len(value) <= cls.RESOURCE_ID_MAX_LENGTH else ""

@classmethod
def _atvp_plugin_decode_resource_id(cls, value):
    raw = str(value or "").strip()
    prefix = str(cls.ATVP_PLUGIN_CANDIDATE_POLICY.get("resource_prefix") or "")
    if not prefix or not raw.startswith(prefix) or len(raw) > cls.RESOURCE_ID_MAX_LENGTH:
        return None
    try:
        encoded = raw[len(prefix):]
        encoded += "=" * ((4 - len(encoded) % 4) % 4)
        payload = json.loads(base64.urlsafe_b64decode(encoded).decode("utf-8"))
    except Exception:
        return None
    plugin_id = cls._positive_int((payload or {}).get("plugin"), 0)
    raw_id = str((payload or {}).get("id") or "").strip()
    if (
            plugin_id not in (cls.ATVP_PLUGIN_CANDIDATE_POLICY.get("allowlist") or {})
            or not cls._atvp_plugin_raw_id_safe(raw_id)):
        return None
    return {"plugin_id": plugin_id, "raw_id": raw_id}

def _atvp_plugin_search_site(self, site, queries, deadline=None):
    plugin_id = self._positive_int((site or {}).get("plugin_id"), 0)
    wrapper = self._atvp_plugin_wrapper(site, deadline=deadline)
    with self._atvp_plugin_lock:
        call_lock = self._atvp_plugin_call_locks.setdefault(plugin_id, threading.Lock())
    remaining = (
        deadline - time.monotonic()
        if deadline is not None and math.isfinite(deadline) else 18
    )
    if remaining <= 0 or not call_lock.acquire(timeout=remaining):
        raise RuntimeError("插件候选正在执行")
    try:
        rows = []
        seen = set()
        limit = self._positive_int(
            self.ATVP_PLUGIN_CANDIDATE_POLICY.get("search_limit"), 8,
        )
        for query in list(queries or [])[:2]:
            if len(rows) >= limit:
                break
            result = wrapper.searchContent(str(query or ""), False, "1")
            for value in self._payload_list(result, limit=limit - len(rows)):
                raw_id = str(value.get("vod_id") or value.get("id") or "").strip()
                resource_id = self._atvp_plugin_encode_resource_id(plugin_id, raw_id)
                if not resource_id or resource_id in seen:
                    continue
                seen.add(resource_id)
                row = {
                    "vod_id": resource_id,
                    "vod_name": str(value.get("vod_name") or value.get("name") or "")[:1024],
                    "vod_pic": str(value.get("vod_pic") or "")[:8192],
                    "vod_remarks": str(value.get("vod_remarks") or "")[:4096],
                    "vod_year": str(value.get("vod_year") or "")[:16],
                    "source": str((site or {}).get("name") or "插件候选")[:256],
                    "_resource_mode": "plugin",
                    "_atvp_plugin_id": plugin_id,
                }
                rows.append(row)
        return rows
    finally:
        call_lock.release()

def _atvp_plugin_candidates(self, item, deadline=None, expected_generation=None):
    with self._cache_lock:
        generation = self._cache_generation if expected_generation is None else expected_generation
        if generation != self._cache_generation:
            return []
    sites = self._atvp_plugin_sites_snapshot()
    title = str((item or {}).get("title") or "").strip()
    if not sites or not title:
        return []
    queries = [title] + self._follow_title_alias_values(item, include_primary=False)
    timeout_seconds = self._positive_int(
        self.ATVP_PLUGIN_CANDIDATE_POLICY.get("timeout"), 18,
    )
    deadline = min(
        deadline if deadline is not None else float("inf"),
        time.monotonic() + timeout_seconds,
    )
    futures = {}
    for site in sites:
        future = self._submit_atvp_plugin_task(
            lambda source=dict(site): self._atvp_plugin_search_site(
                source, queries[:2], deadline=deadline,
            )
        )
        if future is not None:
            futures[future] = site
    rows = []
    try:
        for future in as_completed(futures, timeout=max(0.1, deadline - time.monotonic())):
            site = futures[future]
            try:
                rows.extend(future.result())
            except Exception as exc:
                self._diagnostic_event(
                    "plugin_candidate.failed", "WARN", exc=exc,
                    plugin_id=site.get("plugin_id"),
                )
    except FuturesTimeoutError:
        pass
    finally:
        for future in futures:
            if not future.done():
                future.cancel()
    with self._cache_lock:
        if generation != self._cache_generation:
            return []
    return self._resource_fair_candidate_order(
        rows, item, bound=self._resource_binding_resource_id(item), modes=("plugin",),
    )

def _atvp_plugin_play_handle(self, plugin_id, raw_resource_id, flag, raw_play_id, kind):
    context = {
        "plugin_id": self._positive_int(plugin_id, 0),
        "raw_resource_id": str(raw_resource_id or ""),
        "flag": str(flag or "")[:256],
        "play_id": str(raw_play_id or ""),
        "kind": "alist" if kind == "alist" else "plugin",
    }
    digest = hashlib.sha256(json.dumps(
        context, ensure_ascii=False, sort_keys=True, separators=(",", ":"),
    ).encode("utf-8")).hexdigest()
    handle = "%d-%d" % (
        self._positive_int(self.ATVP_PLUGIN_CANDIDATE_POLICY.get("play_handle_base"), 870000)
        + context["plugin_id"],
        int(digest[:20], 16),
    )
    with self._atvp_plugin_lock:
        self._atvp_plugin_play_handles[handle] = context
        self._atvp_plugin_play_handles.move_to_end(handle)
        limit = self._positive_int(
            self.ATVP_PLUGIN_CANDIDATE_POLICY.get("play_handle_limit"), 2048,
        )
        while len(self._atvp_plugin_play_handles) > limit:
            self._atvp_plugin_play_handles.popitem(last=False)
    return handle

def _atvp_plugin_play_context(self, handle):
    with self._atvp_plugin_lock:
        value = self._atvp_plugin_play_handles.get(str(handle or ""))
        if isinstance(value, dict):
            self._atvp_plugin_play_handles.move_to_end(str(handle or ""))
            return dict(value)
    return None

@classmethod
def _atvp_plugin_reserved_play_handle(cls, value):
    base = cls._positive_int(cls.ATVP_PLUGIN_CANDIDATE_POLICY.get("play_handle_base"), 870000)
    return bool(re.match(r"^%d\d{0,3}-\d{1,30}$" % (base // 1000), str(value or "")))

def _atvp_plugin_rewrite_detail(self, plugin_id, raw_resource_id, detail):
    vod = self._payload_first_vod(detail)
    if not isinstance(vod, dict):
        return {"list": []}
    output = dict(vod)
    source_groups, _limited = _split_bounded_shared(
        output.get("vod_play_from") or "插件线路", "$$$", self.RESOURCE_PLAY_GROUP_SCAN_LIMIT,
    )
