    rewritten_groups = []
    for group_index, group in enumerate(raw_groups):
        source = str(
            source_groups[group_index] if group_index < len(source_groups) else "插件线路"
        ).strip() or "插件线路"
        rewritten = []
        parts, _parts_limited = _split_bounded_shared(
            group, "#", self.RESOURCE_GROUP_EPISODE_LIMIT,
        )
        for index, part in enumerate(parts, 1):
            name, separator, target = str(part or "").rpartition("$")
            if not separator:
                target = str(part or "").strip()
                name = "线路%d" % index
            target = str(target or "").strip()
            if not target:
                continue
            kind = "alist" if (
                re.match(r"^(?:magnet:|ed2k:)", target, re.I)
                or self._resource_provider_key(target)
            ) else "plugin"
            handle = self._atvp_plugin_play_handle(
                plugin_id, raw_resource_id, source, target, kind,
            )
            rewritten.append("%s$%s" % (name or ("线路%d" % index), handle))
        if rewritten:
            rewritten_sources.append(source)
            rewritten_groups.append("#".join(rewritten))
    for folder in output.get("group") or []:
        if not isinstance(folder, dict) or not isinstance(folder.get("media"), list):
            continue
        source = str(folder.get("name") or "网盘资源").strip() or "网盘资源"
        rewritten = []
        for index, media in enumerate(folder.get("media")[:self.RESOURCE_GROUP_EPISODE_LIMIT], 1):
            if not isinstance(media, dict):
                continue
            target = str(media.get("url") or "").strip()
            if not target:
                continue
            handle = self._atvp_plugin_play_handle(
                plugin_id, raw_resource_id, source, target, "alist",
            )
            name = str(media.get("name") or ("资源%d" % index)).strip() or ("资源%d" % index)
            rewritten.append("%s$%s" % (name, handle))
        if rewritten:
            rewritten_sources.append(source)
            rewritten_groups.append("#".join(rewritten))
    if not rewritten_groups:
        return {"list": []}
    output["vod_play_from"] = "$$$".join(rewritten_sources)
    output["vod_play_url"] = "$$$".join(rewritten_groups)
    output.pop("group", None)
    output.pop("vodFlags", None)
    return {"list": [output]}

def _atvp_plugin_detail(self, resource_id, deadline=None):
    decoded = self._atvp_plugin_decode_resource_id(resource_id)
    if decoded is None:
        raise RuntimeError("插件候选资源 ID 无效")
    site = next((
        row for row in self._atvp_plugin_sites_snapshot()
        if row.get("plugin_id") == decoded["plugin_id"]
    ), None)
    if site is None:
        raise RuntimeError("插件候选已从当前订阅移除")

    def worker():
        wrapper = self._atvp_plugin_wrapper(site, deadline=deadline)
        with self._atvp_plugin_lock:
            call_lock = self._atvp_plugin_call_locks.setdefault(
                decoded["plugin_id"], threading.Lock(),
            )
        remaining = (
            deadline - time.monotonic()
            if deadline is not None and math.isfinite(deadline) else 18
        )
        if remaining <= 0 or not call_lock.acquire(timeout=remaining):
            raise RuntimeError("插件候选正在执行")
        try:
            raw_id = decoded["raw_id"]
            prefix = str(getattr(wrapper, "DETAIL_PREFIX", "atvp_detail:"))
            category_mode = getattr(wrapper, "_category_mode_enabled", None)
            loader = getattr(wrapper, "_load_category_detail_vod", None)
            if (
                    prefix and raw_id.startswith(prefix)
                    and callable(category_mode) and category_mode()
                    and callable(loader)):
                vod = loader(raw_id[len(prefix):])
                result = {"list": [vod]} if isinstance(vod, dict) else {"list": []}
            else:
                result = wrapper.detailContent([raw_id])
            return self._atvp_plugin_rewrite_detail(
                decoded["plugin_id"], raw_id, result,
            )
        finally:
            call_lock.release()

    return self._run_atvp_plugin_task(worker, deadline=deadline)

def _atvp_plugin_player(self, context, deadline=None):
    plugin_id = self._positive_int((context or {}).get("plugin_id"), 0)
    site = next((
        row for row in self._atvp_plugin_sites_snapshot()
        if row.get("plugin_id") == plugin_id
    ), None)
    if site is None:
        raise RuntimeError("插件候选已从当前订阅移除")

    def worker():
        wrapper = self._atvp_plugin_wrapper(site, deadline=deadline)
        with self._atvp_plugin_lock:
            call_lock = self._atvp_plugin_call_locks.setdefault(plugin_id, threading.Lock())
        remaining = (
            deadline - time.monotonic()
            if deadline is not None and math.isfinite(deadline) else 18
        )
        if remaining <= 0 or not call_lock.acquire(timeout=remaining):
            raise RuntimeError("插件候选正在执行")
        try:
            result = wrapper.playerContent(
                str(context.get("flag") or ""),
                str(context.get("play_id") or ""),
                [],
            )
            if isinstance(result, str):
                result = json.loads(result)
            if not isinstance(result, dict) or not result.get("url"):
                raise RuntimeError("插件播放器未返回地址")
            return result
        finally:
            call_lock.release()

    return self._run_atvp_plugin_task(worker, deadline=deadline)

def _atvp_plugin_candidate_gap(self, rows, item):
