    title, year, explicit_series = self._keep_search_profile(cleaned_title)
    normalized = self._normalize_media_title(title)
    if not normalized:
        return None, "empty_title"
    origin = str(self._history_selected_origin or self.atvp_api or "").rstrip("/")
    if (not origin or self._atvp_session is None) and not self._ensure_atvp_connection(force=True):
        raise RuntimeError("客户端TMDB不可达，AList-TVBox回退通道尚未就绪")
    origin = str(self._history_selected_origin or self.atvp_api or "").rstrip("/")
    if not origin:
        raise RuntimeError("AList-TVBox TMDB回退地址无效")
    identity = "%s|%s" % (normalized, year or "")
    marker = hashlib.sha256(identity.encode("utf-8")).hexdigest()[:24]
    backend = hashlib.sha256(origin.encode("utf-8")).hexdigest()[:16]
    cache_key = "tmdb-json:atvp-follow:%s:%s" % (backend, marker)
    cached = self._cache_get(cache_key, self.detail_cache_ttl)
    if isinstance(cached, dict) and self._positive_int(cached.get("id"), 0):
        return dict(cached), ""
    if self._atvp_session is None or not self._atvp_history_login(force=False):
        raise RuntimeError("客户端TMDB不可达，AList-TVBox回退需要History登录账号")
    stable_path = "/__v80_follow_cache__/%s" % marker

    def request(method, endpoint, **kwargs):
        sender = getattr(self._atvp_session, method)
        for attempt in range(2):
            response = sender(
                origin + endpoint,
                timeout=operation.request_timeout(self.timeout),
                verify=self.verify_tls,
                stream=True,
                **kwargs
            )
            if response.status_code in (401, 403) and attempt == 0:
                response.close()
                if not self._atvp_history_login(force=True):
                    break
                continue
            if response.status_code < 200 or response.status_code >= 300:
                status = response.status_code
                response.close()
                raise RuntimeError("AList-TVBox TMDB回退 HTTP %s" % status)
            return self._read_bounded_json_response(
                response, "AList-TVBox TMDB回退",
                deadline=operation.deadline,
                max_bytes=self.RESOURCE_API_RESPONSE_MAX_BYTES,
            )
        raise RuntimeError("AList-TVBox TMDB回退登录已失效")

    def lookup():
        payload = request(
            "get", "/api/tmdb/meta",
            params={"q": stable_path, "page": 0, "size": 10},
        )
        rows = payload.get("content") if isinstance(payload, dict) else []
        return next((
            row for row in rows or []
            if isinstance(row, dict) and str(row.get("path") or "") == stable_path
        ), None)

    with self._v80_timeout_child_scope(
            "atvp_tmdb_fallback", self.RESOURCE_DETAIL_BUDGET) as operation:
        row = lookup()
        detail = None
        if not isinstance(row, dict) or not self._positive_int(row.get("tmId"), 0):
            body = {"path": stable_path, "name": title, "type": "tv"}
            if year:
                body["year"] = year
            scraped = request("post", "/api/tmdb/meta/-/scrape", json=body)
            detail = scraped if isinstance(scraped, dict) else None
            row = lookup()
    if not isinstance(row, dict):
        return None, "no_confident_tv"
    tmdb_id = self._positive_int(row.get("tmId"), 0)
    media_type = str(row.get("type") or "").strip().lower()
    name = str(row.get("name") or (detail or {}).get("vod_name") or "")
    candidate = {
        "id": tmdb_id,
        "name": name,
        "title": name,
        "original_name": "",
        "original_title": "",
        "first_air_date": str(row.get("year") or ""),
        "release_date": str(row.get("year") or ""),
        "poster_path": str((detail or {}).get("vod_pic") or ""),
        "_media_type": media_type,
        "_atvp_fallback": True,
    }
    if isinstance(detail, dict):
        candidate["_atvp_detail"] = {
            "id": tmdb_id,
            "name": str(detail.get("vod_name") or name),
            "poster_path": str(detail.get("vod_pic") or ""),
            "first_air_date": str(detail.get("vod_year") or row.get("year") or ""),
            "overview": str(detail.get("vod_content") or ""),
        }
    ranked = self._rank_keep_candidates(
        [candidate], normalized, year, media_type == "tv", explicit_series,
    )
    if not ranked or ranked[0][0] < 90:
        return None, "no_confident_tv"
    self._cache_set(cache_key, candidate)
    return candidate, ""

def _match_keep_to_tmdb(self, keep):
    title, year, explicit_series = self._keep_search_profile(keep.get("title"))
    normalized = self._normalize_media_title(title)
    if not normalized:
        return None, "empty_title"
    params = {"query": title, "page": 1, "include_adult": "false"}
    tv_rows = self._tmdb_api("/search/tv", params, self.detail_cache_ttl).get("results") or []
    movie_rows = self._tmdb_api("/search/movie", params, self.detail_cache_ttl).get("results") or []
    tv_ranked = self._rank_keep_candidates(tv_rows, normalized, year, True, explicit_series)
    movie_ranked = self._rank_keep_candidates(movie_rows, normalized, year, False, False)
    if not tv_ranked or tv_ranked[0][0] < 90:
        return None, "no_confident_tv"
    if len(tv_ranked) > 1 and tv_ranked[0][0] == tv_ranked[1][0]:
        return None, "ambiguous_tv"
    movie_score = movie_ranked[0][0] if movie_ranked else 0
    if movie_score >= tv_ranked[0][0] and not explicit_series:
        return None, "movie_conflict"
    return tv_ranked[0][2], ""

