@staticmethod
def _local_follow_episode_key(value):
    raw = unicodedata.normalize("NFKC", str(value or ""))
    match = re.search(r"(?i)\bS\s*0*(\d{1,2})\s*E\s*0*(\d{1,3})\b", raw)
    if match:
        return "S%02dE%02d" % (int(match.group(1)), int(match.group(2)))
    matches = re.findall(r"(?:更新至|第)\s*([一二三四五六七八九十百零〇两\d]+)\s*[集话期]", raw)
    if not matches:
        return ""
    token = matches[-1]
    number = int(token) if token.isdigit() else Filter._chinese_number(token)
    return "S01E%02d" % number if number > 0 else ""

def _local_follow_series_evidence(self, keep):
    episode_count = keep.get("number_of_episodes", keep.get("episode_count"))
    if episode_count not in (None, ""):
        count = self._positive_int(episode_count, 0)
        if count <= 1:
            return "", "single_episode"
        return "episode_count:%d" % count, ""
    raw = " ".join(str(keep.get(key) or "") for key in (
        "title", "match_title", "history_remark", "vod_remarks", "type_name",
    ))
    normalized = unicodedata.normalize("NFKC", raw)
    negative = re.search(r"(?i)(?:电影|影片|短片|独立视频|单集(?:视频|节目|项目)?|预告片|\bMV\b)", normalized)
    coordinate = re.search(
        r"(?i)(?:\bS\s*0*\d{1,2}\s*E\s*0*\d{1,3}\b|"
        r"(?:更新至|第)\s*[一二三四五六七八九十百零〇两\d]+\s*[集话期]|"
        r"全\s*(?:[2-9]|\d{2,})\s*[集期])",
        normalized,
    )
    category = re.search(r"(?:电视剧|连续剧|剧集|番剧|动漫|动画剧|综艺|真人秀|脱口秀|连载)", normalized)
    if negative and not coordinate:
        return "", "movie_conflict"
    if coordinate:
        return "episode_coordinate", ""
    if category:
        return "series_category", ""
    return "", "no_confident_tv"

