TMDB_HEDGE_DELAY_SECONDS = 0.8
TMDB_HEDGE_TIMEOUT_SECONDS = 20
TMDB_HEDGE_FAILURE_LIMIT = 3
TMDB_HEDGE_DEGRADE_SECONDS = 60
TMDB_HEDGE_SAMPLE_LIMIT = 8

def _tmdb_hedge_channel_available(self, channel, now=None):
    now = time.time() if now is None else float(now)
    with self._tmdb_hedge_lock:
        state = self._tmdb_hedge_health.get(str(channel)) or {}
        return float(state.get("degraded_until") or 0) <= now

def _tmdb_hedge_record(self, channel, success, latency_ms, hit=False, error=None):
    channel = str(channel or "")
    now = time.time()
    with self._tmdb_hedge_lock:
        state = self._tmdb_hedge_health.setdefault(channel, {
            "samples": [], "consecutive_failures": 0, "degraded_until": 0.0,
        })
        samples = list(state.get("samples") or [])
        samples.append({
            "success": bool(success),
            "hit": bool(hit),
            "latency_ms": max(0, int(latency_ms or 0)),
        })
        state["samples"] = samples[-self.TMDB_HEDGE_SAMPLE_LIMIT:]
        if success:
            state["consecutive_failures"] = 0
            state["degraded_until"] = 0.0
        else:
            failures = self._positive_int(state.get("consecutive_failures"), 0) + 1
            state["consecutive_failures"] = failures
            if failures >= self.TMDB_HEDGE_FAILURE_LIMIT:
                state["degraded_until"] = now + self.TMDB_HEDGE_DEGRADE_SECONDS
        recent = list(state["samples"])
        success_rate = (
            round(sum(1 for sample in recent if sample["success"]) * 100.0 / len(recent), 1)
            if recent else 0.0
        )
        average_latency_ms = (
            int(sum(sample["latency_ms"] for sample in recent) / len(recent))
            if recent else 0
        )
        degraded_until = int(state.get("degraded_until") or 0)
        consecutive_failures = self._positive_int(state.get("consecutive_failures"), 0)
    self._diagnostic_event(
        "tmdb_hedge.channel", "INFO" if success else "WARN", exc=error,
        channel=channel, success=bool(success), hit=bool(hit),
        latency_ms=max(0, int(latency_ms or 0)), success_rate=success_rate,
        average_latency_ms=average_latency_ms,
        consecutive_failures=consecutive_failures, degraded_until=degraded_until,
    )

def _tmdb_hedge_snapshot(self):
    now = time.time()
    output = {}
    with self._tmdb_hedge_lock:
        for channel, state in self._tmdb_hedge_health.items():
            recent = list(state.get("samples") or [])
            output[channel] = {
                "samples": len(recent),
                "success_rate": (
                    round(sum(1 for sample in recent if sample.get("success")) * 100.0 / len(recent), 1)
                    if recent else 0.0
                ),
                "average_latency_ms": (
                    int(sum(self._positive_int(sample.get("latency_ms"), 0) for sample in recent) / len(recent))
                    if recent else 0
                ),
                "consecutive_failures": self._positive_int(state.get("consecutive_failures"), 0),
                "degraded": float(state.get("degraded_until") or 0) > now,
            }
    return output

@staticmethod
def _tmdb_follow_identity_cache_key(normalized, year):
    identity = "%s|%s" % (str(normalized or ""), str(year or ""))
    return "tmdb-json:follow-identity:%s" % hashlib.sha256(
        identity.encode("utf-8")
    ).hexdigest()[:24]

def _tmdb_confident_tv_match(self, match):
    return bool(
        isinstance(match, dict)
        and self._positive_int(match.get("id"), 0)
        and str(match.get("_media_type") or "tv").strip().lower() == "tv"
    )

def _tmdb_client_follow_match(self, keep, title, year, normalized, explicit_series):
    started = time.monotonic()
    match = None
    reason = "no_confident_tv"
    try:
        params = {"query": title, "page": 1, "include_adult": "false"}
        tv_rows = self._tmdb_api("/search/tv", params, self.detail_cache_ttl).get("results") or []
        tv_ranked = self._rank_keep_candidates(
            tv_rows, normalized, year, True, explicit_series,
        )
        if tv_ranked and tv_ranked[0][0] >= 90:
            if len(tv_ranked) > 1 and tv_ranked[0][0] == tv_ranked[1][0]:
                reason = "ambiguous_tv"
            elif explicit_series:
                match = dict(tv_ranked[0][2])
                match["_media_type"] = "tv"
                reason = ""
        if match is None and reason != "ambiguous_tv":
            movie_rows = self._tmdb_api("/search/movie", params, self.detail_cache_ttl).get("results") or []
            movie_ranked = self._rank_keep_candidates(
                movie_rows, normalized, year, False, False,
            )
            movie_score = movie_ranked[0][0] if movie_ranked else 0
            if not tv_ranked or tv_ranked[0][0] < 90:
                reason = "movie_conflict" if movie_score >= 90 else "no_confident_tv"
            elif movie_score >= tv_ranked[0][0]:
                reason = "movie_conflict"
            else:
                match = dict(tv_ranked[0][2])
                match["_media_type"] = "tv"
                reason = ""
    except Exception as exc:
        self._tmdb_hedge_record(
            "client", False, (time.monotonic() - started) * 1000, error=exc,
        )
        raise
    self._tmdb_hedge_record(
        "client", True, (time.monotonic() - started) * 1000,
        hit=self._tmdb_confident_tv_match(match),
    )
    return match, reason

def _tmdb_server_follow_match(self, keep):
    started = time.monotonic()
    try:
        match, reason = self._atvp_tmdb_follow_match(keep)
    except Exception as exc:
        self._tmdb_hedge_record(
            "server", False, (time.monotonic() - started) * 1000, error=exc,
        )
        raise
    self._tmdb_hedge_record(
        "server", True, (time.monotonic() - started) * 1000,
        hit=self._tmdb_confident_tv_match(match),
    )
    return match, reason

